import { getProfileDetails, type GetProfileDetailsResponse } from '~/client';
import type { MaybeRefOrGetter } from 'vue';

export const useProfileDetails = (userId: MaybeRefOrGetter<string | undefined>) => {
  const id = computed(() => toValue(userId));
  const { data, error, isLoading, refetch } = useQuery({
    key: () => ['profile', id.value ?? ''],
    query: (): Promise<GetProfileDetailsResponse> =>
      getProfileDetails({ composable: '$fetch', path: { user_id: id.value as string } }),
    enabled: () => !!id.value,
  });
  return { profileDetails: data, error, isLoading, refetch };
};
